import { test, expect } from '@playwright/test';

test.describe('Dropdown Menu Keyboard Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dropdown');
  });

  test('should navigate dropdown items using arrow keys', async ({ page }) => {
    // Open the dropdown menu
    const dropdownButton = page.getByRole('button', { name: /open dropdown/i });
    await dropdownButton.click();

    // Verify dropdown is visible
    const dropdown = page.locator('[data-testid="dropdown-menu"]');
    await expect(dropdown).toBeVisible();

    // Navigate to the first item using arrow down
    const firstItem = page.getByRole('menuitem', { name: /option 1/i });
    await firstItem.first().press('ArrowDown');
    await expect(firstItem.first()).toBeVisible();

    // Navigate to the last item using arrow down
    const lastItem = page.getByRole('menuitem', { name: /option 5/i });
    await firstItem.first().press('ArrowDown');
    await firstItem.first().press('ArrowDown');
    await firstItem.first().press('ArrowDown');
    await firstItem.first().press('ArrowDown');
    await expect(lastItem).toBeVisible();

    // Navigate back to the first item using arrow up
    await lastItem.press('ArrowUp');
    await expect(firstItem.first()).toBeVisible();

    // Select the first item using Enter
    await firstItem.first().press('Enter');
    await expect(page).toHaveURL(/.*selected/);
  });

  test('should handle keyboard navigation with edge cases', async ({ page }) => {
    // Open the dropdown menu
    const dropdownButton = page.getByRole('button', { name: /open dropdown/i });
    await dropdownButton.click();

    // Verify dropdown is visible
    const dropdown = page.locator('[data-testid="dropdown-menu"]');
    await expect(dropdown).toBeVisible();

    // Navigate to the second item using arrow down
    const secondItem = page.getByRole('menuitem', { name: /option 2/i });
    await firstItem.first().press('ArrowDown');
    await expect(secondItem).toBeVisible();

    // Navigate to the first item using arrow up
    await secondItem.press('ArrowUp');
    await expect(firstItem.first()).toBeVisible();

    // Navigate to the last item using arrow down
    await firstItem.first().press('ArrowDown');
    await firstItem.first().press('ArrowDown');
    await firstItem.first().press('ArrowDown');
    await firstItem.first().press('ArrowDown');
    await expect(lastItem).toBeVisible();

    // Press arrow down when at the last item (should wrap to first)
    await lastItem.press('ArrowDown');
    await expect(firstItem.first()).toBeVisible();

    // Press arrow up when at the first item (should wrap to last)
    await firstItem.first().press('ArrowUp');
    await expect(lastItem).toBeVisible();

    // Close dropdown using Escape key
    await page.keyboard.press('Escape');
    await expect(dropdown).not.toBeVisible();
  });
});
